import { DomainError } from "../domain/errors";
import { advance, cancel, Order, OrderLine, OrderState } from "../domain/order";
import { Product, releaseStock, reserveStock } from "../domain/product";
import { OrderRepository, ProductRepository } from "./ports";

export interface PlaceOrderInput {
  customerId: string;
  items: { productId: string; quantity: number }[];
}

export type Transition = "pay" | "pack" | "ship" | "deliver";

const TRANSITION_TARGET: Record<Transition, OrderState> = {
  pay: "paid",
  pack: "packed",
  ship: "shipped",
  deliver: "delivered",
};

export class FulfilmentService {
  constructor(
    private readonly products: ProductRepository,
    private readonly orders: OrderRepository,
  ) {}

  addProduct(id: string, name: string, stock: number): Product {
    if (!id || !name) throw new DomainError("validation", "id and name are required");
    if (!Number.isInteger(stock) || stock < 0) {
      throw new DomainError("validation", "stock must be a non-negative integer");
    }
    if (this.products.get(id)) throw new DomainError("conflict", `Product ${id} already exists`);
    const product: Product = { id, name, stock };
    this.products.save(product);
    return product;
  }

  listProducts(): Product[] {
    return this.products.list();
  }

  getProduct(id: string): Product {
    const product = this.products.get(id);
    if (!product) throw new DomainError("not_found", `Product ${id} not found`);
    return product;
  }

  placeOrder(input: PlaceOrderInput): Order {
    if (!input.customerId) throw new DomainError("validation", "customerId is required");
    if (input.items.length === 0) throw new DomainError("validation", "An order needs at least one item");

    const quantities = new Map<string, number>();
    for (const item of input.items) {
      if (!item.productId) throw new DomainError("validation", "productId is required");
      if (!Number.isInteger(item.quantity) || item.quantity <= 0) {
        throw new DomainError("validation", "quantity must be a positive integer");
      }
      quantities.set(item.productId, (quantities.get(item.productId) ?? 0) + item.quantity);
    }

    const lines: OrderLine[] = [];
    const reserved: { product: Product; quantity: number }[] = [];
    try {
      for (const [productId, quantity] of quantities) {
        const product = this.getProduct(productId);
        reserveStock(product, quantity);
        reserved.push({ product, quantity });
        lines.push({ productId, quantity });
      }
    } catch (error) {
      for (const r of reserved) releaseStock(r.product, r.quantity);
      throw error;
    }

    const order: Order = {
      id: this.orders.nextId(),
      customerId: input.customerId,
      lines,
      state: "placed",
      createdAt: new Date(),
    };
    this.orders.save(order);
    return order;
  }

  getOrder(id: string): Order {
    const order = this.orders.get(id);
    if (!order) throw new DomainError("not_found", `Order ${id} not found`);
    return order;
  }

  listOrders(state?: OrderState): Order[] {
    return this.orders.list(state);
  }

  transition(id: string, transition: Transition): Order {
    const order = this.getOrder(id);
    advance(order, TRANSITION_TARGET[transition]);
    this.orders.save(order);
    return order;
  }

  cancelOrder(id: string): Order {
    const order = this.getOrder(id);
    cancel(order);
    for (const line of order.lines) {
      const product = this.products.get(line.productId);
      if (product) releaseStock(product, line.quantity);
    }
    this.orders.save(order);
    return order;
  }
}

